<style>
*{box-sizing:border-box}body{background:#f3f6fb}.verifier-content{padding:20px;flex:1;min-height:0;overflow:hidden;display:flex;flex-direction:column}.page-header-card{background:#fff;border:1px solid #d6dce8;border-radius:12px;padding:18px 20px;margin-bottom:14px;flex-shrink:0;display:flex;justify-content:space-between;align-items:center;gap:14px}.page-header-card h1{margin:0;font-size:24px;color:#111827}.page-header-card p{margin:6px 0 0;font-size:14px;color:#6b7280}.refresh-main{height:42px;border:0;border-radius:10px;background:#374151;color:white;font-weight:900;padding:0 14px;display:inline-flex;align-items:center;gap:7px;cursor:pointer;text-decoration:none}.import-card{background:#fff;border:1px dashed #94a3b8;border-radius:12px;padding:14px;margin-bottom:14px;display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:center;flex-shrink:0}.import-card.dragover{background:#eff6ff;border-color:#2563eb}.import-title{font-weight:900;color:#0f172a}.import-note{font-size:12px;color:#64748b;margin-top:3px}.file-name{font-size:13px;font-weight:800;color:#1d4ed8}.import-btn,.template-btn{height:42px;border:0;border-radius:9px;font-weight:900;padding:0 14px;display:inline-flex;align-items:center;gap:7px;cursor:pointer;text-decoration:none}.import-btn{background:#168fcb;color:white}.template-btn{background:#e5e7eb;color:#111827}.import-result{grid-column:1/-1;display:none;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:10px;font-size:13px;font-weight:800;color:#334155}.toolbar{display:grid;grid-template-columns:1fr 150px 170px 120px auto;gap:10px;margin-bottom:14px;flex-shrink:0;align-items:center}.toolbar input,.toolbar select{height:42px;padding:0 12px;border:1px solid #cbd5e1;border-radius:8px;font-size:14px;background:white;outline:none}.toolbar input:focus,.toolbar select:focus{border-color:#168fcb;box-shadow:0 0 0 3px rgba(22,143,203,.12)}.icon-link{height:42px;min-width:42px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;background:#374151;color:white;text-decoration:none;border:none;cursor:pointer}.sheet-card{background:white;border:1px solid #cbd5e1;border-radius:12px;overflow:hidden;flex:1;min-height:0;display:flex;flex-direction:column}.table-scroll{width:100%;overflow:auto;flex:1;min-height:0}.verifier-table{width:100%;min-width:1030px;border-collapse:collapse;font-size:13px}.verifier-table th{background:#dbeafe;color:#111827;font-weight:800;text-align:left;border-bottom:1px solid #b6c3d5;padding:11px 10px;white-space:nowrap;position:sticky;top:0;z-index:3}.verifier-table td{border-bottom:1px solid #e5e7eb;padding:10px;vertical-align:middle;background:#fff;white-space:nowrap}.verifier-table tbody tr:nth-child(even) td{background:#f9fafb}.verifier-table tbody tr:hover td{background:#eef6ff}.row-priority td{background:#fff7ed!important}.row-priority:hover td{background:#ffedd5!important}.row-number{text-align:center;font-weight:800;color:#475569}.client-name{font-weight:800;color:#111827}.muted-small{color:#6b7280;font-size:12px;display:block;margin-top:2px}.queue-number{font-weight:900;color:#1d4ed8}.priority-queue-number{color:#c2410c!important}.priority-label{display:inline-block;background:#fed7aa;color:#9a3412;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:900;margin-left:6px}.status-badge{display:inline-block;min-width:116px;text-align:center;padding:6px 10px;border-radius:999px;font-size:11px;font-weight:900;text-transform:uppercase}.status-step-2{background:#fef3c7;color:#92400e}.status-called-2{background:#fde68a;color:#78350f}.status-step-3{background:#dbeafe;color:#1e40af}.status-called-3{background:#bfdbfe;color:#1e3a8a}.status-paid{background:#dcfce7;color:#166534}.status-cancelled{background:#fee2e2;color:#991b1b}.status-none{background:#e5e7eb;color:#374151}.action-group{display:flex;gap:6px;justify-content:center}.action-group form{margin:0}.icon-btn{width:36px;height:36px;border:none;border-radius:8px;color:white;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;text-decoration:none}.icon-btn .material-icons{font-size:19px}.btn-regular{background:#16a34a}.btn-priority{background:#dc2626}.btn-regenerate{background:#f97316}.btn-view{background:#2563eb}.btn-remove{background:#991b1b}.icon-btn:disabled{background:#9ca3af;cursor:not-allowed}.icon-btn:hover:not(:disabled){opacity:.88}.footer-note{padding:10px 12px;font-size:12px;color:#6b7280;background:#f9fafb;border-top:1px solid #d1d5db;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;flex-shrink:0}.pagination{display:flex;align-items:center;justify-content:center;gap:8px;padding:10px 12px;border-top:1px solid #d1d5db;background:#fff;flex-shrink:0}.page-btn{height:34px;min-width:34px;border:1px solid #cbd5e1;border-radius:7px;background:white;cursor:pointer;font-weight:800}.page-btn:disabled{opacity:.45;cursor:not-allowed}.page-info{font-size:13px;color:#475569;font-weight:700}.empty-state,.loading-text{text-align:center;padding:22px;color:#6b7280;font-weight:800}.modal-overlay{display:none;position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9999;justify-content:center;align-items:center;padding:20px}.modal-box{width:420px;max-width:96%;background:#fff;border-radius:14px;padding:24px;box-shadow:0 14px 40px rgba(0,0,0,.25)}.details-box{width:760px}.modal-box h2{margin:0;color:#111827;font-size:22px}.modal-box p{margin:8px 0 20px;color:#4b5563;font-size:14px}.modal-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px}.modal-btn{height:46px;border:none;border-radius:10px;color:white;font-weight:900;cursor:pointer;font-size:15px}.pal-btn{background:#16a34a}.prio-btn{background:#dc2626}.modal-cancel{width:100%;height:42px;border:none;border-radius:10px;background:#e5e7eb;color:#111827;font-weight:900;cursor:pointer}.details-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.detail-item{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:10px}.detail-item span{display:block;font-size:11px;color:#64748b;font-weight:800;text-transform:uppercase;margin-bottom:4px}.detail-item strong{display:block;color:#111827;font-size:13px;word-break:break-word}@media(max-width:1000px){.toolbar{grid-template-columns:1fr 1fr}.import-card{grid-template-columns:1fr}.verifier-table{min-width:980px}}@media(max-width:700px){.page-header-card{flex-direction:column;align-items:flex-start}.toolbar{grid-template-columns:1fr}.details-grid{grid-template-columns:1fr}.verifier-content{overflow:visible}.sheet-card{min-height:520px}}
