<body>
<div class="app"><main class="main"><section class="verifier-content">
<div class="page-header-card"><div><h1>Step 1: Verify</h1><p>Search beneficiary records, import CSV/Excel data, view details, and generate queue numbers.</p></div><button class="refresh-main" onclick="manualRefresh()"><span class="material-icons">refresh</span>Refresh</button></div>
<div class="import-card" id="dropZone"><div><div class="import-title"><span class="material-icons" style="vertical-align:middle;font-size:19px;">upload_file</span> Import Beneficiaries CSV / Excel</div><div class="import-note">Drag and drop a CSV or Excel .xlsx file here, or click upload. New records appear after import.</div><div class="file-name" id="fileName">No file selected</div></div><input type="file" id="importFile" accept=".csv,.xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden><button type="button" class="template-btn" onclick="downloadTemplate()"><span class="material-icons">download</span>CSV Template</button><button type="button" class="import-btn" onclick="chooseFile()"><span class="material-icons">file_upload</span>Upload File</button><div class="import-result" id="importResult"></div></div>
<div class="toolbar"><input type="text" id="searchInput" placeholder="Search name, queue, barangay, LGU..."><select id="typeFilter"><option value="all">All Types</option><option value="priority">PRIO Only</option><option value="regular">PAL Only</option><option value="none">No Queue</option></select><select id="statusFilter"><option value="all">All Status</option><option value="WAITING_STEP_2">Waiting Step 2</option><option value="CALLED_STEP_2">Called Step 2</option><option value="WAITING_STEP_3">Waiting Step 3</option><option value="CALLED_STEP_3">Called Step 3</option><option value="PAID">Paid</option><option value="none">No Queue</option></select><select id="rowsPerPage"><option value="10">10 rows</option><option value="25" selected>25 rows</option><option value="50">50 rows</option><option value="100">100 rows</option></select><button class="icon-link" onclick="manualRefresh()" title="Refresh"><span class="material-icons">refresh</span></button></div>
<div class="sheet-card"><div class="table-scroll"><table class="verifier-table"><thead><tr><th style="width:55px;text-align:center;">#</th><th style="width:135px;">Queue No.</th><th>Name</th><th>Barangay</th><th style="width:70px;">Age</th><th style="width:70px;">Sex</th><th>LGU</th><th style="width:145px;">Status</th><th style="width:220px;text-align:center;">Actions</th></tr></thead><tbody id="beneficiaryRows"><tr><td colspan="9" class="loading-text">Loading beneficiaries...</td></tr></tbody></table></div><div class="pagination" id="paginationControls"></div><div class="footer-note"><span id="recordInfo">Showing records...</span><span id="lastUpdated">Last updated: --</span></div></div>
</section></main><?php include('sidebar.php'); ?></div>
<div id="regenerateModal" class="modal-overlay"><div class="modal-box"><h2>Choose Queue Type</h2><p>Select the new queue type for this beneficiary.</p><form id="regenerateForm" method="POST" action="../api/regenerate_qn.php"><input type="hidden" name="beneficiary_id" id="regenBeneficiaryId"><input type="hidden" name="new_queue_type" id="regenQueueType"><div class="modal-actions"><button type="button" class="modal-btn pal-btn" onclick="submitRegenerate('PAL')">PAL</button><button type="button" class="modal-btn prio-btn" onclick="submitRegenerate('PRIO')">PRIO</button></div><button type="button" class="modal-cancel" onclick="closeRegenerateModal()">Cancel</button></form></div></div>
<div id="detailsModal" class="modal-overlay"><div class="modal-box details-box"><h2>Beneficiary Details</h2><p>Complete record view without cluttering the main table.</p><div class="details-grid" id="detailsGrid"></div><button type="button" class="modal-cancel" onclick="closeDetailsModal()">Close</button></div></div>
<script>
const searchInput=document.getElementById('searchInput'),typeFilter=document.getElementById('typeFilter'),statusFilter=document.getElementById('statusFilter'),rowsPerPage=document.getElementById('rowsPerPage'),tableBody=document.getElementById('beneficiaryRows'),lastUpdated=document.getElementById('lastUpdated'),recordInfo=document.getElementById('recordInfo'),paginationControls=document.getElementById('paginationControls'),dropZone=document.getElementById('dropZone'),importFile=document.getElementById('importFile'),fileName=document.getElementById('fileName'),importResult=document.getElementById('importResult');let beneficiaries=[],currentPage=1,selectedImportFile=null;
function escapeHTML(value){if(value===null||value===undefined)return'';return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
function displayStatus(status){if(status==='WAITING_STEP_2')return'Waiting Step 2';if(status==='CALLED_STEP_2')return'Called Step 2';if(status==='WAITING_STEP_3')return'Waiting Step 3';if(status==='CALLED_STEP_3')return'Called Step 3';if(status==='PAID')return'Paid';if(status==='CANCELLED')return'Cancelled';return'No Queue'}
function statusClass(status){if(status==='WAITING_STEP_2')return'status-step-2';if(status==='CALLED_STEP_2')return'status-called-2';if(status==='WAITING_STEP_3')return'status-step-3';if(status==='CALLED_STEP_3')return'status-called-3';if(status==='PAID')return'status-paid';if(status==='CANCELLED')return'status-cancelled';return'status-none'}
function getFullName(row){const middle=row.middle_name?' '+row.middle_name:'';const ext=row.ext_name?' '+row.ext_name:'';return `${row.last_name||''}, ${row.first_name||''}${middle}${ext}`.trim()}
function getFilteredRows(){const searchValue=searchInput.value.toLowerCase().trim(),typeValue=typeFilter.value,statusValue=statusFilter.value;return beneficiaries.filter(row=>{const hasQueue=row.queue_number&&row.queue_number!=='';const searchable=[row.queue_number,row.last_name,row.first_name,row.middle_name,row.ext_name,row.barangay,row.city_municipality,row.lgu,row.contact_number,row.beneficiary_code].join(' ').toLowerCase();if(searchValue&&!searchable.includes(searchValue))return false;if(typeValue==='priority'&&row.queue_type!=='priority')return false;if(typeValue==='regular'&&row.queue_type!=='regular')return false;if(typeValue==='none'&&hasQueue)return false;if(statusValue==='none'&&hasQueue)return false;if(statusValue!=='all'&&statusValue!=='none'&&row.workflow_status!==statusValue)return false;return true})}
function renderPagination(totalRows,totalPages){if(totalRows===0){paginationControls.innerHTML='';return}paginationControls.innerHTML=`<button class="page-btn" onclick="goToPage(1)" ${currentPage===1?'disabled':''}>«</button><button class="page-btn" onclick="goToPage(${currentPage-1})" ${currentPage===1?'disabled':''}>‹</button><span class="page-info">Page ${currentPage} of ${totalPages}</span><button class="page-btn" onclick="goToPage(${currentPage+1})" ${currentPage===totalPages?'disabled':''}>›</button><button class="page-btn" onclick="goToPage(${totalPages})" ${currentPage===totalPages?'disabled':''}>»</button>`}
function goToPage(page){const filtered=getFilteredRows(),perPage=parseInt(rowsPerPage.value,10),totalPages=Math.max(1,Math.ceil(filtered.length/perPage));currentPage=Math.min(Math.max(1,page),totalPages);renderTable()}
function renderTable(){const filtered=getFilteredRows(),perPage=parseInt(rowsPerPage.value,10),totalPages=Math.max(1,Math.ceil(filtered.length/perPage));if(currentPage>totalPages)currentPage=totalPages;const startIndex=(currentPage-1)*perPage,pageRows=filtered.slice(startIndex,startIndex+perPage);if(pageRows.length===0){tableBody.innerHTML='<tr><td colspan="9" class="empty-state">No beneficiaries found.</td></tr>';recordInfo.innerText=`Showing 0 of ${beneficiaries.length} records`;renderPagination(0,1);return}let html='';pageRows.forEach((row,index)=>{const hasQueue=row.queue_number&&row.queue_number!=='';const isPriority=row.queue_type==='priority';const rowClass=isPriority?'row-priority':'';const queueNumberClass=isPriority?'queue-number priority-queue-number':'queue-number';const priorityLabel=isPriority?'<span class="priority-label">PRIO</span>':'';const fullName=getFullName(row);const actualNumber=startIndex+index+1;html+=`<tr class="${rowClass}"><td class="row-number">${actualNumber}</td><td class="${queueNumberClass}">${hasQueue?escapeHTML(row.queue_number)+priorityLabel:'Not generated'}</td><td><span class="client-name">${escapeHTML(fullName)}</span><span class="muted-small">${escapeHTML(row.beneficiary_code||'No code')}</span></td><td>${escapeHTML(row.barangay)}</td><td>${escapeHTML(row.age)}</td><td>${escapeHTML(row.sex)}</td><td>${escapeHTML(row.lgu)}</td><td><span class="status-badge ${statusClass(row.workflow_status)}">${displayStatus(row.workflow_status)}</span></td><td><div class="action-group"><button type="button" class="icon-btn btn-view" title="View Details" onclick="openDetailsModal('${escapeHTML(row.id)}')"><span class="material-icons">visibility</span></button><form method="POST" action="../api/generate_regular_qn.php" onsubmit="return confirm('Generate PAL queue number for this beneficiary?');"><input type="hidden" name="beneficiary_id" value="${escapeHTML(row.id)}"><button type="submit" class="icon-btn btn-regular" title="Generate PAL" ${hasQueue?'disabled':''}><span class="material-icons">add_circle</span></button></form><form method="POST" action="../api/generate_priority_qn.php" onsubmit="return confirm('Generate PRIO queue number for this beneficiary?');"><input type="hidden" name="beneficiary_id" value="${escapeHTML(row.id)}"><button type="submit" class="icon-btn btn-priority" title="Generate PRIO" ${hasQueue?'disabled':''}><span class="material-icons">priority_high</span></button></form><button type="button" class="icon-btn btn-regenerate" title="Regenerate Queue" onclick="openRegenerateModal('${escapeHTML(row.id)}')" ${!hasQueue?'disabled':''}><span class="material-icons">sync</span></button><form method="POST" action="../api/remove_beneficiary.php" onsubmit="return confirm('Remove this beneficiary and all related queue/payout records?');"><input type="hidden" name="beneficiary_id" value="${escapeHTML(row.id)}"><input type="hidden" name="redirect" value="../staff/verifier.php"><button type="submit" class="icon-btn btn-remove" title="Remove Beneficiary"><span class="material-icons">delete</span></button></form></div></td></tr>`});tableBody.innerHTML=html;recordInfo.innerText=`Showing ${startIndex+1}-${Math.min(startIndex+perPage,filtered.length)} of ${filtered.length} filtered records (${beneficiaries.length} total)`;renderPagination(filtered.length,totalPages)}
function openRegenerateModal(id){document.getElementById('regenBeneficiaryId').value=id;document.getElementById('regenQueueType').value='';document.getElementById('regenerateModal').style.display='flex'}function closeRegenerateModal(){document.getElementById('regenerateModal').style.display='none';document.getElementById('regenBeneficiaryId').value='';document.getElementById('regenQueueType').value=''}function submitRegenerate(type){if(type!=='PAL'&&type!=='PRIO'){alert('Invalid queue type.');return}if(!confirm('Regenerate queue number as '+type+'?'))return;document.getElementById('regenQueueType').value=type;document.getElementById('regenerateForm').submit()}function openDetailsModal(id){const row=beneficiaries.find(item=>String(item.id)===String(id));if(!row)return;const birthday=row.birthday_month&&row.birthday_day&&row.birthday_year?`${row.birthday_month}/${row.birthday_day}/${row.birthday_year}`:'';const details=[['Beneficiary Code',row.beneficiary_code],['Queue Number',row.queue_number||'Not generated'],['Queue Type',row.queue_type||'None'],['Status',displayStatus(row.workflow_status)],['Last Name',row.last_name],['First Name',row.first_name],['Middle Name',row.middle_name],['Ext. Name',row.ext_name],['Region',row.region],['Province',row.province],['City/Municipality',row.city_municipality],['Barangay',row.barangay],['Contact Number',row.contact_number],['Birthday',birthday],['Age',row.age],['Sex',row.sex],['LGU',row.lgu]];document.getElementById('detailsGrid').innerHTML=details.map(item=>`<div class="detail-item"><span>${escapeHTML(item[0])}</span><strong>${escapeHTML(item[1]||'-')}</strong></div>`).join('');document.getElementById('detailsModal').style.display='flex'}function closeDetailsModal(){document.getElementById('detailsModal').style.display='none'}document.getElementById('regenerateModal').addEventListener('click',function(event){if(event.target===this)closeRegenerateModal()});document.getElementById('detailsModal').addEventListener('click',function(event){if(event.target===this)closeDetailsModal()});
async function loadVerifierData(){try{const response=await fetch('../api/verifier_data.php?ts='+Date.now(),{cache:'no-store'});if(!response.ok)throw new Error('Failed to load verifier data.');const data=await response.json();if(!data.success){tableBody.innerHTML=`<tr><td colspan="9" class="empty-state">${escapeHTML(data.message)}</td></tr>`;return}beneficiaries=data.beneficiaries;renderTable();lastUpdated.innerText='Last updated: '+new Date().toLocaleTimeString()}catch(error){console.error(error);tableBody.innerHTML='<tr><td colspan="9" class="empty-state">Failed to load data.</td></tr>'}}function manualRefresh(){loadVerifierData()}
function chooseFile(){importFile.click()}function setImportFile(file){if(!file)return;const lower=file.name.toLowerCase();if(!lower.endsWith('.csv')&&!lower.endsWith('.xlsx')){showImportResult('Please upload CSV or Excel .xlsx file only. Legacy .xls is not supported.',false);return}selectedImportFile=file;fileName.innerText=file.name;uploadImportFile()}function showImportResult(message,success=true){importResult.style.display='block';importResult.style.borderColor=success?'#86efac':'#fecaca';importResult.style.background=success?'#f0fdf4':'#fef2f2';importResult.style.color=success?'#166534':'#991b1b';importResult.innerHTML=message}
async function uploadImportFile(){if(!selectedImportFile){showImportResult('No file selected.',false);return}showImportResult('Importing, please wait...',true);const formData=new FormData();formData.append('import_file',selectedImportFile);try{const response=await fetch('../api/import_beneficiaries.php',{method:'POST',body:formData});const data=await response.json();if(!data.success){showImportResult(escapeHTML(data.message||'Import failed.'),false);return}let msg=`Imported: ${data.inserted||0} | Duplicates skipped: ${data.duplicates||0} | Failed rows: ${data.failed||0}`;if(data.errors&&data.errors.length){msg+=`<br><small>${data.errors.map(escapeHTML).join('<br>')}</small>`}showImportResult(msg,true);selectedImportFile=null;importFile.value='';fileName.innerText='No file selected';currentPage=1;loadVerifierData()}catch(error){console.error(error);showImportResult('Import failed. Please check the file format.',false)}}
importFile.addEventListener('change',()=>setImportFile(importFile.files[0]));['dragenter','dragover'].forEach(evt=>dropZone.addEventListener(evt,e=>{e.preventDefault();dropZone.classList.add('dragover')}));['dragleave','drop'].forEach(evt=>dropZone.addEventListener(evt,e=>{e.preventDefault();dropZone.classList.remove('dragover')}));dropZone.addEventListener('drop',e=>setImportFile(e.dataTransfer.files[0]));function downloadTemplate(){const csv='last_name,first_name,middle_name,ext_name,birthday,age,sex,contact_number,id_presented,household_id,region,province,city_municipality,barangay,lgu,program_type,pwd\nDela Cruz,Juan,Santos,,01/15/1980,44,Male,09171234567,PhilSys ID,HH-001,Region IV-A,Cavite,Imus City,Alapan I-A,Imus City,AICS,No\n';const blob=new Blob([csv],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='beneficiary_import_template.csv';a.click();URL.revokeObjectURL(url)}
[searchInput,typeFilter,statusFilter,rowsPerPage].forEach(element=>{element.addEventListener('input',()=>{currentPage=1;renderTable()});element.addEventListener('change',()=>{currentPage=1;renderTable()})});loadVerifierData();setInterval(loadVerifierData,5000);
</script>
</body>
</html>